def count_pentagons_small(n):
    count = 0
    for x1 in range(1, n - 3):
        lb = max(1, (n // 2 + 1) - x1)
        upper_sum = n - x1 - 2
        if upper_sum >= 2 * lb:
            M = upper_sum - 2 * lb
            count += (M + 1) * (M + 2) // 2
    return count * 5

print(count_pentagons_small(7))

def solve():
    count = 0
    # x1+x2+x3+x4+x5 = 101, xi >= 1
    # y1=x5+x1, y2=x1+x2, y3=x2+x3, y4=x3+x4, y5=x4+x5
    # count exactly two yj >= 51
    # Number of pentagons is sum(x5)
    for x1 in range(1, 101):
        for x2 in range(1, 101 - x1):
            for x3 in range(1, 101 - x1 - x2):
                for x4 in range(1, 101 - x1 - x2 - x3):
                    x5 = 101 - x1 - x2 - x3 - x4
                    if x5 >= 1:
                        y = [x5 + x1, x1 + x2, x2 + x3, x3 + x4, x4 + x5]
                        acute_count = sum(1 for val in y if val >= 51)
                        if acute_count == 2:
                            count += x5
    return count

