def count_gap_sequences_optimized(n):
    count = 0
    half_n = (n + 1) // 2 # 51 for n=101
    for x1 in range(1, n - 3):
        for x2 in range(1, n - x1 - 2):
            for x3 in range(1, n - x1 - x2 - 1):
                S = n - x1 - x2 - x3
                if S < 2: continue

                y2_acute = (x1 + x2 >= half_n)
                y3_acute = (x2 + x3 >= half_n)
                y5_acute = (S >= half_n)

                current_acute = int(y2_acute) + int(y3_acute) + int(y5_acute)

                A = S + x1 - half_n
                B = half_n - x3

                needed = 2 - current_acute
                if needed == 0:
                    lower = max(1, A + 1)
                    upper = min(S - 1, B - 1)
                    if lower <= upper:
                        count += (upper - lower + 1)
                elif needed == 1:
                    upper1 = min(S - 1, A, B - 1)
                    if upper1 >= 1:
                        count += upper1
                    lower2 = max(1, A + 1, B)
                    upper2 = S - 1
                    if lower2 <= upper2:
                        count += (upper2 - lower2 + 1)
                elif needed == 2:
                    lower = max(1, B)
                    upper = min(S - 1, A)
                    if lower <= upper:
                        count += (upper - lower + 1)
    return count

