import itertools
from math import comb

def count_for_n(n):
    count = 0
    for combo in itertools.combinations(range(n), 5):
        v = list(combo)
        x = [v[1]-v[0], v[2]-v[1], v[3]-v[2], v[4]-v[3], n+v[0]-v[4]]
        y = []
        for i in range(5):
            y.append(x[i-1] + x[i])
        acute_angles = sum(1 for val in y if val >= (n+1)//2)
        if acute_angles == 2:
            count += 1
    return count

