def S_formula(n):
    limit = (n+1)//2
    s1 = 0
    for x1 in range(3, limit):
        s1 += comb(x1, 3)
    s2 = 0
    for x1 in range(limit, n-1):
        s2 += comb(n-4-x1+3, 3)
    return s1 + s2

for n in [7, 8, 9, 10, 11]:
    S = S_formula(n)
    print(f"n={n}, S={S}, n/5*S={n*S/5}")

